import React from 'react';

export default function About(){
  return (
    <div className="about">
      <h2>About Us</h2>
      <p>We are a community-driven NGO platform that connects volunteers and donors to projects that need them.</p>
      <p>This demo app shows a simple structure for role-based access and basic features like donations, volunteering and feedback.</p>
    </div>
  );
}
